export enum ROLES {
  ADMIN = 'ADMIN',
  USER = 'USER',
}

type RoleTypes = keyof typeof ROLES;

import { queryOptions, useQuery } from '@tanstack/react-query';

import { api } from '@/lib/api-client';
import { QueryConfig } from '@/lib/react-query';
import { User } from '@/types/api';

export type GetUsersParams = {
  role?: 'ADMIN' | 'USER';
  search?: string;
};

export const getUsers = (
  params?: GetUsersParams,
): Promise<{ data: User[] }> => {
  return api.get(`/users`, { params });
};

export const getUsersQueryOptions = (params?: GetUsersParams) => {
  return queryOptions({
    queryKey: ['users', params],
    queryFn: () => getUsers(params),
  });
};

type UseUsersOptions = {
  queryConfig?: QueryConfig<typeof getUsersQueryOptions>;
};

export const useUsers = ({
  queryConfig,
  params,
}: UseUsersOptions & { params?: GetUsersParams } = {}) => {
  return useQuery({
    ...getUsersQueryOptions(params),
    ...queryConfig,
  });
};

import { Search, X } from 'lucide-react';
import { useState } from 'react';

import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/form';
import { Select } from '@/components/ui/form';
import { Spinner } from '@/components/ui/spinner';
import { Table } from '@/components/ui/table';
import { formatDate } from '@/utils/format';

import { useUsers } from '../api/get-users';

import { DeleteUser } from './delete-user';

type UsersListProps = {
  onExport?: (users: Parameters<typeof downloadUsersCsv>[0]) => void;
  renderExportButton?: (props: { onClick: () => void }) => React.ReactNode;
};

export const UsersList = ({ onExport, renderExportButton }: UsersListProps) => {
  const [role, setRole] = useState<string>();
  const [search, setSearch] = useState<string>();

  const usersQuery = useUsers({ params: { role, search } });

  if (usersQuery.isLoading) {
    return (
      <div className="flex h-48 w-full items-center justify-center">
        <Spinner size="lg" />
      </div>
    );
  }

  const users = usersQuery.data?.data;

  if (!users) return null;

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-4">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            placeholder="Search by name or email"
            className="pl-9"
            value={search ?? ''}
            onChange={(e) => setSearch(e.target.value || undefined)}
          />
        </div>
        <Select
          label=""
          options={[
            { label: 'All Roles', value: '' },
            { label: 'Admin', value: 'ADMIN' },
            { label: 'User', value: 'USER' },
          ]}
          defaultValue={role ?? ''}
          className="w-40"
          registration={{
            onChange: (e: React.ChangeEvent<HTMLSelectElement>) =>
              setRole(e.target.value || undefined),
          }}
        />
        {role || search ? (
          <Button
            variant="outline"
            size="sm"
            icon={<X className="size-4" />}
            onClick={() => {
              setRole(undefined);
              setSearch(undefined);
            }}
          >
            Clear
          </Button>
        ) : null}
      </div>
      <Table
        data={users}
        columns={[
          {
            title: 'First Name',
            field: 'firstName',
          },
          {
            title: 'Last Name',
            field: 'lastName',
          },
          {
            title: 'Email',
            field: 'email',
          },
          {
            title: 'Role',
            field: 'role',
          },
          {
            title: 'Created At',
            field: 'createdAt',
            Cell({ entry: { createdAt } }) {
              return <span>{formatDate(createdAt)}</span>;
            },
          },
          {
            title: '',
            field: 'id',
            Cell({ entry: { id } }) {
              return <DeleteUser id={id} />;
            },
          },
        ]}
      />
      {renderExportButton &&
        renderExportButton({
          onClick: () => onExport?.(users),
        })}
    </div>
  );
};

import {
  randCompanyName,
  randUserName,
  randEmail,
  randParagraph,
  randUuid,
  randPassword,
  randCatchPhrase,
} from '@ngneat/falso';

const ROLES = ['ADMIN', 'USER'] as const;

const generateUser = () => ({
  id: randUuid() + Math.random(),
  firstName: randUserName({ withAccents: false }),
  lastName: randUserName({ withAccents: false }),
  email: randEmail(),
  password: randPassword(),
  teamId: randUuid(),
  teamName: randCompanyName(),
  role: ROLES[Math.floor(Math.random() * ROLES.length)],
  bio: randParagraph(),
  createdAt: Date.now(),
});

export const createUser = <T extends Partial<ReturnType<typeof generateUser>>>(
  overrides?: T,
) => {
  return { ...generateUser(), ...overrides };
};

const generateTeam = () => ({
  id: randUuid(),
  name: randCompanyName(),
  description: randParagraph(),
  createdAt: Date.now(),
});

export const createTeam = <T extends Partial<ReturnType<typeof generateTeam>>>(
  overrides?: T,
) => {
  return { ...generateTeam(), ...overrides };
};

const generateDiscussion = () => ({
  id: randUuid(),
  title: randCatchPhrase(),
  body: randParagraph(),
  createdAt: Date.now(),
});

export const createDiscussion = <
  T extends Partial<ReturnType<typeof generateDiscussion>>,
>(
  overrides?: T & {
    authorId?: string;
    teamId?: string;
  },
) => {
  return { ...generateDiscussion(), ...overrides };
};

const generateComment = () => ({
  id: randUuid(),
  body: randParagraph(),
  createdAt: Date.now(),
});

export const createComment = <
  T extends Partial<ReturnType<typeof generateComment>>,
>(
  overrides?: T & {
    authorId?: string;
    discussionId?: string;
  },
) => {
  return { ...generateComment(), ...overrides };
};

